package web

import (
	"context"
	"encoding/json"
	"flag"
	"io"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"syscall"
	"testing"
	"time"
)

var memoryNativeReceipt = flag.String("memory-native-receipt", "", "opt-in native UI fixture receipt (new file, no credentials)")
var memoryNativeV2 = flag.Bool("memory-native-v2", false, "serve a historical V2 store in the native UI fixture only")

// This opt-in fixture runs the real Go server and built React in an installed
// Lake Dev client. It has no alternate routes or fetch mocks. Its Home is always
// generated by testing; neither a caller-supplied Home nor production V2 enablement
// is possible. SIGINT/SIGTERM or the deadline stops the server and releases Home.
func TestMemoryRetirementNativeDev(t *testing.T) {
	if *memoryNativeReceipt == "" {
		t.Skip("manual native UI fixture: pass -memory-native-receipt NEW_FILE")
	}
	home := t.TempDir()
	assets := filepath.Join("..", "..", "assets", "web", "dist")
	if _, err := os.Stat(filepath.Join(assets, "index.html")); err != nil {
		t.Fatal("build fresh Web assets with scripts/build_lake.sh before native acceptance", err)
	}
	t.Setenv("LAKE_WEB_TOKEN", "")
	ctx, stop := signal.NotifyContext(context.Background(), os.Interrupt, syscall.SIGTERM)
	defer stop()
	ctx, cancel := context.WithTimeout(ctx, 25*time.Minute)
	defer cancel()
	b, err := New(ctx, Options{Home: home, DataDir: filepath.Join(home, "web-agent"),
		DynamicPort: true, Static: os.DirFS(assets), Output: io.Discard, memoryV2ForTest: *memoryNativeV2})
	if err != nil {
		t.Fatal(err)
	}
	defer b.Close()
	if b.Models.Active() != nil {
		t.Fatal("native fixture unexpectedly has a model")
	}
	project := stringOf(b.Store.CreateProject("PR169 客户端验收")["id"])
	if !*memoryNativeV2 {
		b.Store.CommitProjectMemory(project, MemoryMutation{Key: "backup-check", Type: "project",
			Description: "合成验收记忆", Body: "发布前检查备份。", Verification: "user-stated", SourceKind: "manual-ui"})
		// A terminal historical job must remain visible, never dispatchable.
		b.Store.update(func() any {
			b.Store.exec(`INSERT INTO projectMemoryTurns(projectId,sessionId,turnId,epoch,knowledgeBaseRevision,snapshotJSON,snapshotHash,modelRefJSON,outcome,createdAt)
VALUES(?,'historical-session','historical-turn',0,0,'{"schemaVersion":2}','synthetic','{}','blocked',?)`, project, now())
			sequence := integer(b.Store.row("SELECT sequence FROM projectMemoryTurns WHERE projectId=? AND turnId='historical-turn'", project)["sequence"])
			b.Store.exec("INSERT INTO projectMemoryJobs(jobId,turnSequence,status,attempts,lastErrorCode,createdAt,updatedAt) VALUES('native-retired-job',?,'blocked',3,?,?,?)", sequence, retiredMemoryV2Code, now(), now())
			return nil
		})
	}
	l, server, err := b.prepareHTTPServer()
	if err != nil {
		t.Fatal(err)
	}
	served := make(chan error, 1)
	go func() { served <- server.Serve(l) }()
	file, err := os.OpenFile(*memoryNativeReceipt, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
	if err != nil {
		t.Fatal(err)
	}
	err = json.NewEncoder(file).Encode(Object{"home": home, "projectId": project, "memoryV2Fixture": *memoryNativeV2,
		"modelConfigured": false, "backendPID": os.Getpid()})
	closeErr := file.Close()
	if err != nil || closeErr != nil {
		t.Fatal("write native fixture receipt", err, closeErr)
	}
	t.Log("native fixture ready; generated Home, no model, no browser")
	select {
	case <-ctx.Done():
	case err := <-served:
		if err != nil && err != http.ErrServerClosed {
			t.Fatal(err)
		}
	}
}
